function knapsack(pesos, valores, capacidad) {
  const dp = new Array(capacidad + 1).fill(0);
  const n = pesos.length;
  for (let i = 0; i < n; i++) {
    for (let w = capacidad; w >= pesos[i]; w--) {
      const cand = dp[w - pesos[i]] + valores[i];
      if (cand > dp[w]) dp[w] = cand;
    }
  }
  return dp[capacidad];
}

