def prefijos_fenwick(n, operaciones):
    bit = [0] * (n + 1)

    def add(i, delta):
        j = i + 1
        while j <= n:
            bit[j] += delta
            j += j & -j

    def prefix(i):
        s = 0
        j = i + 1
        while j > 0:
            s += bit[j]
            j -= j & -j
        return s

    salida = []
    for op in operaciones:
        if op[0] == "add":
            add(op[1], op[2])
        else:
            salida.append(prefix(op[1]))
    return salida

